import math
from enum import Enum
from numbers import Real


class Mode(Enum):
    ACTIVE = "active"
    RECOVERING = "recovering"


def _number(value):
    return isinstance(value, Real) and not isinstance(value, bool) and math.isfinite(value)


def inside_interval(value, lower, upper):
    if not all(_number(item) for item in (value, lower, upper)) or lower > upper:
        raise ValueError("invalid interval")
    return lower <= value <= upper


def interval_midpoint(lower, upper):
    if not _number(lower) or not _number(upper) or lower > upper:
        raise ValueError("invalid interval")
    return (lower + upper) / 2


class SafetyRunner:
    def __init__(self):
        self.mode = Mode.ACTIVE
        self.finished = False
        self.recovery = None

    def tick(self, value, lower, upper, work, recovery_factory):
        safe = inside_interval(value, lower, upper)
        if self.finished:
            return None
        if self.mode is Mode.ACTIVE:
            if safe:
                result = work.step()
                if result:
                    self.finished = True
                return result
            self.recovery = recovery_factory(interval_midpoint(lower, upper))
            self.mode = Mode.RECOVERING
        result = self.recovery.step()
        if result:
            self.recovery = None
            self.mode = Mode.ACTIVE
        return result

